// Alex: full advisor profile with separate financial, page and note collections.
MATCH (s:Employee)-[:COVERS_ADVISOR]->(a:Advisor {id:'ADV-101'})
CALL (a) {
 MATCH (a)-[:MEMBER_OF]->(b:BuyingUnit)-[p:POSITION_AS_OF]->(i:Instrument)-[:OF_FUND]->(fund:Fund)
 WHERE p.as_of=date('2026-09-29') AND p.currency='USD'
 MATCH (b)-[f:FLOW_IN_PERIOD]->(i)
 WHERE f.period_start=date('2026-09-01') AND f.period_end=date('2026-09-30') AND f.currency='USD'
 RETURN collect({fund:fund.name,ticker:i.ticker,as_of:p.as_of,assets_usd:p.assets_cents/100.0,
 sales_usd:f.sales_cents/100.0,redemptions_usd:f.redemptions_cents/100.0,net_flow_usd:f.net_flow_cents/100.0}) AS financials
}
CALL (a) {
 MATCH (a)-[v:VISITED_PAGE]->(p:Document)
 WHERE v.period_start=date('2026-09-01') AND v.period_end=date('2026-09-30')
 RETURN collect({page:p.name,url:p.source_url,visits:v.visit_count,last_seen:v.last_seen}) AS visited_pages
}
CALL (a) {
 MATCH (i:Interaction)-[:WITH_ADVISOR]->(a),(i)-[:DOCUMENTED_IN]->(d:Document)-[:HAS_VERSION]->(v:DocumentVersion)-[:HAS_CHUNK]->(c:ContentChunk)
 WHERE v.lifecycle='CURRENT'
 RETURN collect({type:i.interaction_type,date:i.occurred_on,note:c.text,next_action:i.next_action,follow_up_due:i.follow_up_due}) AS conversations
}
RETURN properties(a) AS advisor,s.full_name AS salesperson,financials,visited_pages,conversations;
